package com.coffeeshop.service;import com.coffeeshop.model.AuditModels;import com.coffeeshop.repository.AuditRepository;import java.time.LocalDate;import java.util.*;public final class AuditService{private final AuditRepository repository;public AuditService(AuditRepository r){repository=Objects.requireNonNull(r);}public List<AuditModels.Entry>entries(String search,LocalDate from,LocalDate to){if(from==null||to==null)throw new IllegalArgumentException("Select a start and end date.");if(to.isBefore(from))throw new IllegalArgumentException("End date cannot precede start date.");if(from.plusYears(1).isBefore(to))throw new IllegalArgumentException("Audit range cannot exceed one year.");return repository.find(search==null?"":search.trim(),from,to);}}
